  [286217962816768] = "Proteção de perfuração",
  [286218231247104] = "Evoca um Axe Knight no local alvo para realizar uma clivagem, causando dano de Spellfielddisc(*id) aos inimigos ao alcance, com 70% de chance de <Highlight> atordoar </> inimigos na área central.",
  [286218231247616] = "Invoque Yodora no local alvo. Yodora invoca um círculo mágico que irrompe após um pequeno atraso, causando *d de dano ao alvo duas vezes, depois aumentando o dano causado ao alvo em 6% e reduzindo o dano causado pelo alvo em 6% por 6 segundos.",
  [286218231248384] = "Evoca um Eyes of Mystery Prying no local alvo para se conectar ao alvo, causando *d de dano a cada 0,5 segundos por 5 segundos. O link é quebrado se o alvo se afastar uma certa distância dos Olhos do Inquisidor Misterioso.",
