  [286218231249408] = "Invoque um Cavaleiro Mágico para se abençoar com buffdisc(*id) por 10 segundos.",
  [286218231249920] = "Evoca uma Borboleta Imaginária para possuir o alvo, concedendo buffdisc(*id) por 6 segundos.",
  [286218231250432] = "Invoque um Megose Phantom no local alvo para realizar um ataque duplo na frente. O primeiro golpe causa *d dano e <Highlight> Estagnação </> ; o segundo golpe causa *d dano e inflige <Highlight> Ferimento Grave </> . Os inimigos atingidos pelo primeiro ataque sofrem 50% de dano adicional; o segundo ataque também fornece um aumento temporário de dano às unidades aliadas vizinhas.",
  [286218231251200] = "Invoque um Face-Ripper para disparar balas ricocheteantes contra os inimigos ao alcance. As balas saltam entre unidades aliadas e inimigas próximas, causando dano de bulletdisc(*id) ao atingir os inimigos e aplicando buffdisc(*id) ao atingir unidades aliadas.",
  [286218231251712] = "Invoque Luper, o Lobo Alfa, para realizar três Golpes de Garra consecutivos, cada um causando *d de dano e tendo 50% de chance de atordoar o alvo por 0,3 segundos. Concede buffdisc(*id) a si mesmo durante os 8 segundos em que o lobo é convocado.",
  [286218231252224] = "Invoque um Drill para se proteger, ganhando Super Armor e buffdisc(*id) durante a duração. Quando atacado, causa 20% de lentidão ao atacante por 1 segundo, durando <Highlight> 4 </> segundos.",
  [286218768118016] = "Evoca um Cavaleiro de Machado no local alvo para causar dano aos inimigos ao alcance e atordoar os que estão no centro.",
  [286218768118528] = "Invoque Yodora no local alvo; após um pequeno atraso, ele causa dano ao alvo, aumenta o dano subsequente causado ao alvo e reduz o dano causado pelo alvo.",
