  [286218231219968] = "Condense instantaneamente três Sombras de Sabujo Escarlate em uma área em forma de leque à sua frente, lançando uma Mordida para causar *d dano.",
  [286218231220480] = "Transforma-se instantaneamente em um cão de caça e avança 20 metros, causando *d de dano aos inimigos no caminho.",
  [286218231221504] = "Evoca um Marionete transformado de um Star Worm para liberar Eyes of Mystery Prying, removendo o escudo de Spellfielddisc(*id) dos inimigos dentro do alcance do Marionete e causando dano de Spellfielddisc(*id).",
  [286218231222016] = "Invoca um Marionete transformado de Star Worm para liberar um Sunset Hurricane, atingindo continuamente os inimigos em um raio de 4,5 metros do Marionete. A cada <Highlight> 0,4 </> segundos, ele causa *d de dano e aplica uma lentidão de 1,2 segundo <Highlight> 25% </> aos inimigos na área, durando <Highlight> 5 </> segundos.",
  [286218231223296] = "Evoca um babuíno à sua frente, com duração de 21 segundos. Ao ser invocado e a cada <Highlight> 6 </> segundos depois disso, o babuíno aplicará um buff aleatório aos companheiros de equipe em um raio de 30 metros. \nBuffs aleatórios: buffdisc(*id), com duração de <Highlight> 6 </> segundos; buffdisc(*id), com duração de <Highlight> 6 </> segundos; buffdisc(*id), com duração de <Highlight> 6 </> segundos;",
  [286218231226624] = "Invoca o espírito de Sylvia para possuí-lo, com duração de 30 segundos. Durante a posse, buffdisc(*id) causa dano de bulletdisc(*id), que pode ser acionado uma vez por segundo, até 7 vezes.",
  [286218231227648] = "Acumule 5 pilhas de Golden Might para causar dano de bulletdisc(*id) a um único alvo.",
  [286218231228416] = "Acumule 5 pilhas de Poder Dourado para causar dano de bulletdisc(*id) a um único alvo e criar uma Explosão, causando dano de Spellfielddisc(*id) aos inimigos em um raio de 10 metros do alvo.",
  [286218231228928] = "Convoque a Viscondessa para atacar o alvo. \nSe o alvo for um jogador: A Viscondessa causa dano de bulletdisc(*id) e aplica Possessão Fantasma por 10 segundos, aumentando seu dano ao alvo em 6% durante a posse. Se o alvo morrer em 10 segundos, o fantasma procurará aleatoriamente outro jogador inimigo em um raio de 15 metros para causar dano de bulletdisc(*id) e possuí-lo, até 1 posse adicional. \nSe o alvo for um monstro: O fantasma causa dano de bulletdisc(*id) ao monstro duas vezes e o possui por 15 segundos, aumentando seu dano ao monstro em 6% durante a posse.",
  [998771022366208] = "Reivindicação de Alma Fantasmagórica",
  [286218231229696] = "Transforme-se em um baiacu, explodindo após um pequeno atraso e disparando <Highlight> 4 </> balas em todas as direções, cada uma causando *d de dano. Você ganha <Highlight> Super Armadura </> durante toda a duração da transformação.",
  [286218231231744] = "Invoque Ancestor Armor e crie um círculo mágico com um raio de 30 metros a seus pés, durando <Highlight> 10 </> segundos, fazendo com que aliados dentro do alcance usem buffdisc(*id). \nProteção Ancestral: Cada vez que você cura ativamente um aliado 3 vezes, gera Proteção Ancestral a seus pés com um raio de 5 metros, com duração de 2,5 segundos. Pode ser acionado no máximo uma vez a cada 4 segundos, fazendo com que os aliados dentro do alcance usem buffdisc(*id). \nO círculo mágico e a Proteção Ancestral não podem existir simultaneamente, e no máximo uma Proteção Ancestral pode existir por vez.",
  [286218231233280] = "Após a ativação, entre em Invisibilidade por <Highlight> 3 </> segundos e convoque 3 ilusões de Selena em um raio de 3,5 metros ao seu redor para liberar Explosão de Espelho. Cada ilusão causa *d de dano aos inimigos em um raio de 3,5 metros. O dano é reduzido em 50% para cada facada repetida recebida.",
  [286218231234304] = "Transforme-se e disfarce-se aleatoriamente como um objeto de cena por 10 segundos. Durante esse tempo, você não poderá se mover ou usar habilidades e não sofrerá nenhum dano. Você pode cancelar a transformação usando a habilidade novamente.",
  [286218231234816] = "Evoca um Marionete transformado de Star Worm para liberar Miracle Card Rain, causando dano de Spellfielddisc(*id) aos inimigos em um raio de 4,5 metros do alvo, com uma probabilidade básica de *f** para <HyperLink stylename=\"M_Link\" u=\"6\"> atordoar </> inimigos no centro da área por 0,8 segundos, até <HighLight> atordoar </> 2 pessoas.",
  [286218231235328] = "Evoca um Marionete transformado de Star Worm para liberar Punição, causando *d de dano aos inimigos em um raio de 4 metros do Marionete.",
  [286218231235840] = "Evoca um Marionete transformado de Star Worm para liberar Dream Analysis, criando um domínio com um raio de 6 metros que cura continuamente aliados dentro do domínio, restaurando *d Health por segundo por <HighLight> 6 </> segundos.",
  [286218231236608] = "Evoca um Minion Imaginário perto de um único inimigo em um raio de 15 metros. Depois que o Minion Imaginário levita, ele dispara continuamente <HighLight> 4 </> balas rastreadoras no alvo, cada uma causando dano de bulletdisc(*id).",
  [286218231238144] = "Evoca um Marionete transformado de Worm of Star para lançar Exile, causando <HighLight> 5 </> ocorrências de *d dano a inimigos em um raio de 5 metros do alvo, seguido por um <HighLight> Finish </> que causa *d dano. Ao atacar monstros, um efeito adicional de <HyperLink stylename=\"M_Link\" u=\"2\" color=\"#f4a067\"> Pull </> em direção ao centro é aplicado.",
  [286218231238912] = "Invoque um Marionete transformado de Verme de Estrela para liberar aleatoriamente Sopro de Chama de Gelo ou Sopro de Gelo em linha reta à frente. \nIce Flame Breath: Causa *d de dano aos inimigos em seu caminho e inflige <HyperLink stylename=\"M_Link\" u=\"10\"> Ferimento Grave </> por <HighLight> 68% </> de *d segundos. \nFrost Breath: Causa *d de dano aos inimigos em seu caminho e tem 70% de chance de aplicar buffdisc(*id) ao inimigo por *f segundos.",
  [286218231239936] = "Evoca um Marionete transformado de Verme de Estrela para liberar Nebula Slash, causando *d de dano aos inimigos em um raio de 4 metros do alvo.",
  [286218231240960] = "Evoca um Marionete transformado de Worm of Star para liberar um Spinning Slash, causando dano aos inimigos em seu caminho e <HighLight> Knockback </> .",
  [286218231241472] = "Invoque um Marionete transformado de Worm of Star para liberar a habilidade Star Trace, implantando um Star Gate para atacar inimigos em um alcance à sua frente. Se você não possuir <HighLight> Energia Arcana </> ao lançar, você ganha <HighLight> Energia Arcana </> por 70 segundos. Se você já possui <HighLight> Energia Arcana </> , um Star Gate adicional será implantado e a duração da <HighLight> Energia Arcana </> será renovada.",
  [286218231241984] = "Evoca um Marionete transformado de Verme de Estrela para liberar o Hino Solar, causando *d de dano aos inimigos em um raio de 12 metros de você.",
  [286218231242752] = "Evoca um Marionete transformado de Verme de Estrela para liberar Corona Verdict, balançando um feixe de espada que causa *d de dano aos inimigos em um alcance à frente, seguido por um feixe de espada estonteante que causa *d de dano aos inimigos em seu caminho.",
  [286218231243520] = "Invoque a Crente Número Um, Anthea, para remover os efeitos de controle do alvo e restaurar *d Saúde. Também pode ser usado enquanto estiver sob controle.",
  [286218231244032] = "Evoca um usuário do Astrolábio no local alvo para chutar o inimigo, causando *d dano, removendo *d Escudo e infligindo Atordoamento. Seguido por um chute direto causando *d dano; se a Saúde do alvo estiver abaixo de 20%, o chute direto causa *d de dano.",
  [286218231244800] = "Evoca uma tartaruga gigante no local alvo para girar no lugar e espirrar água, causando *d de dano três vezes, seguido por uma batida no solo que causa *d de dano. Os inimigos atingidos pela água serão continuamente afetados por Fraqueza e Estagnação.",
  [286218231245824] = "Evoca um Boneco Coelho à sua frente para bater sua cabeça no chão, causando *d de dano aos inimigos em uma área em forma de leque à sua frente, ao mesmo tempo que cria um tremor secundário que causa *d de dano aos inimigos próximos.",
  [286218231246592] = "Invoque um Palhaço no local alvo. O show de entrada do Palhaço detonará continuamente bombas de fita ao seu redor por 3 segundos. Durante este período, ele causa dano de Spellfielddisc(*id) aos alvos dentro do alcance a cada 0,5 segundos, enquanto restaura Saúde igual a 50% do dano causado (cada restauração não excede 2% de sua Saúde máxima).",
  [286218768090880] = "Manifeste instantaneamente três Scarlet Hound Shadows à sua frente, que executam uma mordida conjunta, causando dano massivo.",
  [286218768091392] = "Transforme-se instantaneamente em um Cão de Caça e avança uma longa distância, causando dano aos inimigos em seu caminho.",
  [286218768092416] = "Evoca um Marionete transformado de um Verme de Estrela para liberar Olhos de Inquisição Misteriosa, removendo uma parte dos Escudos dos inimigos dentro do raio do Marionete e causando dano.",
  [286218768092928] = "Evoca um Marionete transformado de Worm of Star para liberar um Sunset Hurricane, atingindo continuamente os inimigos ao redor do Marionete para causar dano e aplicar Lentidão.",
  [286218768090624] = "Evoca um Cão de Caça Alienado para saltar sobre alvos próximos, causando alto dano e Knockup.",
  [286218768105728] = "Evoca um Marionete transformado de Worm of Star para liberar Miracle Card Rain, causando dano aos inimigos dentro do alcance alvo e atordoando os inimigos no centro da área.",
  [286218768098560] = "Carregue totalmente o Golden Power para causar dano a um único alvo.",
  [286218768099328] = "Carregue totalmente o Poder Dourado para causar dano a um único alvo e desencadear uma Explosão, causando dano aos inimigos próximos.",
  [286218768099840] = "Convoque uma Viscondessa para atacar o alvo. \nSe o alvo for um jogador: Causa dano uma vez e aplica Reivindicação de Alma Fantasmagórica; durante esse tempo, o dano causado ao alvo aumenta. Se o alvo morrer dentro de um determinado período, o fantasma procurará outro jogador inimigo próximo para possuir. \nSe o alvo for um monstro: O fantasma causa dano adicional ao monstro e o possui, aumentando o dano causado a esse monstro durante a duração.⟦",
  [286218768100608] = "Transforme-se em um Baiacu, explodindo após um pequeno atraso e disparando múltiplas balas em todas as direções. Você tem Super Armor durante toda a transformação.",
  [286218768101632] = "Evoca uma Sombra Ouroboros para liberar uma onda de choque de Turbulência Negra, seguida pela habilidade de acionar manualmente uma segunda onda de choque de Turbulência Negra em 6 segundos. \nTurbulência Negra: Eficaz apenas contra inimigos, repelindo-os enquanto aplica Dano Contínuo; se um inimigo morrer durante este período, ocorre uma explosão no local. \nTurbulência Branca: Eficaz apenas contra unidades aliadas, restaurando instantaneamente uma certa quantidade de Saúde e aumentando a velocidade de movimento e redução de dano pelos próximos 8 segundos.",
  [286218768102656] = "Invoque a Armadura Ancestral para adicionar um círculo mágico a você, concedendo melhorias às unidades aliadas dentro do alcance.",
  [286218768104192] = "Entre na Invisibilidade e convoque a Phantom Selena em um anel ao seu redor para desencadear uma Explosão de Espelho, causando danos massivos.",
  [286218768097536] = "Invoque um espírito para possuir você; quando o jogador usa uma habilidade, o espírito causa dano ao alvo.",
  [286218768106240] = "Evoca um Marionete transformado de Verme de Estrela para desencadear Punição, causando dano aos inimigos dentro do raio de Marionete.",
  [286218768106752] = "Invoque um Marionete transformado de Verme de Estrela para liberar a Análise de Sonhos, criando um Reino de Sonhos pacífico que restaura continuamente a Saúde de unidades aliadas na área.",
  [286218768107520] = "Evoque um Minion Imaginário perto dos inimigos e, em seguida, dispare várias balas rastreadoras para causar alto dano.",
  [286218768109056] = "Evoca um Marionete transformado de Verme de Estrela para liberar Exílio, causando dano contínuo aos inimigos dentro do alcance alvo. Aplica um efeito de coleta adicional aos monstros.",
  [286218768109824] = "Invoque um Marionete transformado de um Verme de Estrela para liberar aleatoriamente Sopro de Chama ou Sopro de Gelo. \nFlame Breath: Causa dano aos inimigos em seu caminho e aplica Ferimento Grave. \nFrost Breath: Causa dano aos inimigos em seu caminho e aplica Lentidão.",
  [286218768110848] = "Evoca um Marionete transformado de Worm of Star para liberar Nebula Slash, causando dano aos inimigos dentro do alcance alvo.",
  [286218768111872] = "Evoca um Marionete transformado de Worm of Star para liberar um Spinning Slash, causando dano aos inimigos em seu caminho e Knockback.",
  [286218768112384] = "Invoque um Marionete transformado de Worm of Star para liberar a habilidade Star Trace, implantando um Star Gate para atacar inimigos em um alcance à sua frente.",
  [286218768112896] = "Evoca um Marionete transformado de Verme de Estrela para liberar o Hino Solar, causando dano de área.",
  [286218768113664] = "Evoca um Marionete transformado de Verme de Estrela para liberar Corona Verdict, balançando um feixe de espada que causa dano aos inimigos em um alcance à frente, seguido por um feixe de espada estonteante que causa dano aos inimigos em seu caminho.",
  [286218768114432] = "Convoque a Crente Número Um, Anthea, para remover o controle do alvo e restaurar a Saúde.",
  [286218768114944] = "Convoca um usuário do Astrolábio no local alvo para executar um chute de 2 estágios no alvo, causando dano, com dano aumentado contra alvos com pouca saúde.",
  [286218768115712] = "Evoca uma tartaruga gigante no local alvo para girar no lugar e espirrar água, causando dano aos inimigos e infligindo efeitos negativos.",
  [286218768116736] = "Invoque um Boneco Coelho à sua frente para bater sua cabeça no chão, derrubando os inimigos em uma área em forma de leque à sua frente, ao mesmo tempo que aplica um tremor secundário lento.",
  [286218768117504] = "Evoca um Palhaço no local alvo, causando dano continuamente aos alvos dentro do alcance e restaurando a Saúde com base no dano causado.",
  [998771022396928] = "Respiração de Chama de Gelo",
  [998771022398464] = "Hino Solar",
