  [286218768123136] = "Invoque um Drill para se proteger, ganhando Super Armadura e um Escudo, além de retardar os atacantes.",
  [286218768122624] = "Invoque Luper, o Lobo Alfa, para atacar os inimigos, causando Atordoamento e adicionando um buff de Ataque a você mesmo.",
